series.data_generator:
const a = entity.attributes;
const now = Date.now();
const pts = [[now, 0, 0]];
[...(a.charge_periods || []), ...(a.discharge_periods || [])].forEach(r => {
  pts.push([Math.max(new Date(r.start).getTime(), now), r.power, 1]);
  pts.push([new Date(r.end).getTime(), 0, 0]);
});
if (a.plan_until) pts.push([new Date(a.plan_until).getTime(), 0, 0]);
pts.sort((x, y) => x[0] - y[0] || x[2] - y[2]);
return pts.map(p => [p[0], p[1]]);
